-- Pre-baked 3D travel paths (swim and free flight).
-- Generated by src/tools/nav3d_travel_baker. Not part of the 2D travel graph:
-- a node pair can have a walk path and a 3D path at the same time.

CREATE TABLE IF NOT EXISTS `playerbots_travelnode_link3d` (
`node_id` mediumint(8) NOT NULL,
`to_node_id` mediumint(8) NOT NULL,
`type` tinyint(3) NOT NULL,
`distance` float NOT NULL DEFAULT 0,
`swim_distance` float NOT NULL DEFAULT 0,
`extra_cost` float NOT NULL DEFAULT 0,
`calculated` tinyint(1) NOT NULL DEFAULT 0,
PRIMARY KEY (`node_id`,`to_node_id`,`type`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8 ROW_FORMAT=FIXED COMMENT='PlayerbotAI Travel Node 3D link';

CREATE TABLE IF NOT EXISTS `playerbots_travelnode_path3d` (
`node_id` mediumint(8) NOT NULL,
`to_node_id` mediumint(8) NOT NULL,
`type` tinyint(3) NOT NULL,
`nr` mediumint(8) NOT NULL,
`map_id` mediumint(8) NOT NULL,
`x` float NOT NULL,
`y` float NOT NULL,
`z` float NOT NULL,
PRIMARY KEY (`node_id`,`to_node_id`,`type`,`nr`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8 ROW_FORMAT=FIXED COMMENT='PlayerbotAI Travel Node 3D path';

CREATE TABLE IF NOT EXISTS `playerbots_travelnode_bake` (
`id` tinyint(3) unsigned NOT NULL,
`nav3d_hash` bigint(20) unsigned NOT NULL DEFAULT 0,
`mmap_hash` bigint(20) unsigned NOT NULL DEFAULT 0,
`node_hash` bigint(20) unsigned NOT NULL DEFAULT 0,
`baker_version` varchar(32) NOT NULL DEFAULT '',
`generated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
PRIMARY KEY (`id`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8 COMMENT='PlayerbotAI Travel Node 3D bake metadata';
